-- Reviewed legacy auth schema; generated by scripts/capture_users_schema.py.
CREATE TABLE IF NOT EXISTS users (
                id TEXT PRIMARY KEY,
                email TEXT UNIQUE NOT NULL,
                display_name TEXT NOT NULL,
                password_hash TEXT NOT NULL,
                role TEXT NOT NULL DEFAULT 'employee',
                status TEXT NOT NULL DEFAULT 'active',
                created_at TEXT NOT NULL,
                updated_at TEXT NOT NULL,
                last_login TEXT,
                must_change_password INTEGER NOT NULL DEFAULT 0,
                bootstrap_owner INTEGER NOT NULL DEFAULT 0
            );

            CREATE TABLE IF NOT EXISTS user_agent_bindings (
                user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
                agent_name TEXT NOT NULL,
                access_level TEXT NOT NULL DEFAULT 'owner',
                bound_at TEXT NOT NULL,
                PRIMARY KEY (user_id, agent_name)
            );

            CREATE TABLE IF NOT EXISTS auth_audit_log (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id TEXT,
                action TEXT NOT NULL,
                target TEXT,
                detail TEXT,
                ip TEXT,
                timestamp TEXT NOT NULL
            );

            CREATE INDEX IF NOT EXISTS idx_audit_timestamp ON auth_audit_log(timestamp);
            CREATE INDEX IF NOT EXISTS idx_audit_user ON auth_audit_log(user_id);
            CREATE INDEX IF NOT EXISTS idx_bindings_agent ON user_agent_bindings(agent_name);

            -- Passwordless channel OTP login (WP12). A verified 1:1 channel DM
            -- identity ties a person's messaging account to their user record;
            -- OTP challenges are short-lived, single-use, attempt-capped.
            CREATE TABLE IF NOT EXISTS channel_identities (
                user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
                channel TEXT NOT NULL,
                channel_user_id TEXT NOT NULL,
                verified INTEGER NOT NULL DEFAULT 0,
                created_at TEXT NOT NULL,
                PRIMARY KEY (channel, channel_user_id)
            );
            CREATE INDEX IF NOT EXISTS idx_chid_user ON channel_identities(user_id);

            CREATE TABLE IF NOT EXISTS otp_challenges (
                id TEXT PRIMARY KEY,
                user_id TEXT NOT NULL,
                code_hash TEXT NOT NULL,
                channel TEXT NOT NULL,
                channel_user_id TEXT NOT NULL,
                created_at TEXT NOT NULL,
                expires_at TEXT NOT NULL,
                attempts INTEGER NOT NULL DEFAULT 0,
                consumed INTEGER NOT NULL DEFAULT 0
            );
            CREATE INDEX IF NOT EXISTS idx_otp_user ON otp_challenges(user_id);
            CREATE INDEX IF NOT EXISTS idx_otp_created ON otp_challenges(created_at);

            -- First-run / break-glass admin bootstrap tokens (host-access root).
            CREATE TABLE IF NOT EXISTS setup_tokens (
                id TEXT PRIMARY KEY,
                token_hash TEXT NOT NULL,
                created_at TEXT NOT NULL,
                expires_at TEXT NOT NULL,
                consumed INTEGER NOT NULL DEFAULT 0
            );
ALTER TABLE user_agent_bindings ADD COLUMN is_primary INTEGER NOT NULL DEFAULT 0 CHECK (is_primary IN (0, 1));
CREATE UNIQUE INDEX IF NOT EXISTS idx_bindings_primary ON user_agent_bindings(agent_name) WHERE is_primary = 1;
         CREATE TRIGGER IF NOT EXISTS google_primary_owner_insert BEFORE INSERT ON user_agent_bindings
           WHEN NEW.is_primary = 1 AND NEW.access_level != 'owner' BEGIN SELECT RAISE(ABORT, 'primary binding must be owner'); END;
         CREATE TRIGGER IF NOT EXISTS google_primary_owner_update BEFORE UPDATE ON user_agent_bindings
           WHEN NEW.is_primary = 1 AND NEW.access_level != 'owner' BEGIN SELECT RAISE(ABORT, 'primary binding must be owner'); END;
         CREATE TABLE IF NOT EXISTS google_identity_consents (
           user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
           agent_name TEXT NOT NULL,
           state TEXT NOT NULL CHECK (state IN ('allowed', 'declined')),
           decided_at TEXT NOT NULL,
           decided_by TEXT NOT NULL,
           CHECK (decided_by = user_id),
           PRIMARY KEY (user_id, agent_name)
         );
ALTER TABLE users ADD COLUMN credential_epoch INTEGER NOT NULL DEFAULT 0;
ALTER TABLE channel_identities ADD COLUMN verified_at INTEGER;
CREATE TABLE IF NOT EXISTS mfa_policy_state (
        id INTEGER PRIMARY KEY CHECK(id=1), enforced INTEGER NOT NULL, enforced_at INTEGER);
        CREATE TABLE IF NOT EXISTS mfa_credentials (
        user_id TEXT PRIMARY KEY, secret_enc TEXT NOT NULL, last_step INTEGER NOT NULL,
        failed_attempts INTEGER NOT NULL DEFAULT 0, failure_window INTEGER NOT NULL DEFAULT 0);
        CREATE TABLE IF NOT EXISTS mfa_pending (
        user_id TEXT PRIMARY KEY, binding TEXT NOT NULL, secret_enc TEXT NOT NULL,
        expires_at INTEGER NOT NULL, attempts INTEGER NOT NULL DEFAULT 0);
        CREATE TABLE IF NOT EXISTS mfa_recovery_codes (
        user_id TEXT NOT NULL, code_hash TEXT NOT NULL, PRIMARY KEY(user_id, code_hash));
        CREATE TABLE IF NOT EXISTS mfa_challenges (
        token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL, first_factor TEXT NOT NULL,
        purpose TEXT NOT NULL CHECK(purpose IN ('login','enroll')), expires_at INTEGER NOT NULL,
        attempts INTEGER NOT NULL DEFAULT 0, consumed INTEGER NOT NULL DEFAULT 0);
        CREATE INDEX IF NOT EXISTS idx_mfa_challenges_user ON mfa_challenges(user_id);
        CREATE TABLE IF NOT EXISTS mfa_enrollment_proofs (
        token_hash TEXT PRIMARY KEY, session TEXT, code_hash TEXT, kind TEXT NOT NULL,
        verified INTEGER NOT NULL DEFAULT 0);
        CREATE TABLE IF NOT EXISTS mfa_enrollment_codes (
        user_id TEXT PRIMARY KEY, code_hash TEXT NOT NULL, expires_at INTEGER NOT NULL);
        UPDATE users SET credential_epoch=1 WHERE credential_epoch=0
            AND EXISTS(SELECT 1 FROM mfa_credentials WHERE user_id=users.id);
        CREATE TRIGGER IF NOT EXISTS mfa_password_epoch AFTER UPDATE OF password_hash ON users
        WHEN OLD.password_hash != NEW.password_hash
        BEGIN
            UPDATE users SET credential_epoch=CASE WHEN credential_epoch>0 THEN credential_epoch+1 ELSE 0 END WHERE id=NEW.id;
            DELETE FROM mfa_pending WHERE user_id=NEW.id;
            DELETE FROM mfa_challenges WHERE user_id=NEW.id;
            UPDATE auth_meta SET value=value+1 WHERE key='acl_generation';
        END;
ALTER TABLE mfa_enrollment_codes ADD COLUMN challenge TEXT;
            DELETE FROM mfa_enrollment_codes;
CREATE TABLE IF NOT EXISTS user_invites (
            id TEXT PRIMARY KEY,
            user_id TEXT NOT NULL REFERENCES users(id),
            token_sha256 TEXT UNIQUE NOT NULL,
            created_by TEXT NOT NULL,
            created_at INTEGER NOT NULL,
            expires_at INTEGER NOT NULL,
            used_at INTEGER,
            revoked_at INTEGER
         );
         CREATE INDEX IF NOT EXISTS idx_user_invites_user ON user_invites(user_id);
         CREATE TRIGGER IF NOT EXISTS user_invites_revoke_account_change
         AFTER UPDATE OF email,password_hash,status ON users
         WHEN OLD.email != NEW.email OR OLD.password_hash != NEW.password_hash
              OR NEW.status != 'active'
         BEGIN
             INSERT INTO auth_audit_log(user_id,action,target,detail,timestamp)
                 SELECT NEW.id,'user_invite.revoked',NEW.id,id,strftime('%Y-%m-%dT%H:%M:%fZ','now')
                 FROM user_invites WHERE user_id=NEW.id AND used_at IS NULL AND revoked_at IS NULL;
             UPDATE user_invites SET revoked_at=CAST(strftime('%s','now') AS INTEGER)
                 WHERE user_id=NEW.id AND used_at IS NULL AND revoked_at IS NULL;
         END;
ALTER TABLE users ADD COLUMN department TEXT;
ALTER TABLE users ADD COLUMN manager_user_id TEXT;
ALTER TABLE users ADD COLUMN primary_agent_id TEXT;
CREATE INDEX IF NOT EXISTS idx_users_manager ON users(manager_user_id);
             CREATE TABLE IF NOT EXISTS auth_meta (key TEXT PRIMARY KEY, value INTEGER NOT NULL);
             INSERT OR IGNORE INTO auth_meta (key, value) VALUES ('acl_generation', 1);
